/**
 * Shared column helpers for every schema file.
 *
 * Conventions (all modules):
 *  - Primary keys are TEXT holding a numeric-looking id generated by `newId()` (src/lib/id.ts),
 *    e.g. "2000000417". Numeric ids keep GraphQL ID handling trivial.
 *  - Timestamps are ISO-8601 strings (UTC) produced by `nowIso()`.
 *  - JSON columns use `json<T>()` (text with mode json) and are typed via `$type`.
 *  - Ordering uses REAL `position` columns (fractional indexing, see src/lib/position.ts).
 */
import { text } from "drizzle-orm/sqlite-core";
import { newId } from "../../lib/id";
import { nowIso } from "../../lib/time";

/** Text primary key with a generated numeric-looking id. */
export const idPk = (name = "id") =>
  text(name).primaryKey().$defaultFn(() => newId());

/** Text foreign key / id column (no constraint; add `.references()` in the schema file). */
export const idRef = (name: string) => text(name);

export const createdAt = () =>
  text("created_at")
    .notNull()
    .$defaultFn(() => nowIso());

export const updatedAt = () =>
  text("updated_at")
    .notNull()
    .$defaultFn(() => nowIso())
    .$onUpdateFn(() => nowIso());

/** JSON stored as text. Always pass the TS type: `json<MyType>("settings")`. */
export const json = <T>(name: string) => text(name, { mode: "json" }).$type<T>();
